using System;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
public static class TrainingFrontInstall {
 [MenuItem("Shioka/Play/Open title scene")]public static void Open(){if(EditorApplication.isPlaying)throw new Exception("Stop Play first");if(!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;EditorSceneManager.OpenScene(TrainingFlowSession.TitleScene);}
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Edit mode only");if(System.IO.File.Exists(TrainingFlowSession.TitleScene))throw new Exception("Existing title scene must not be overwritten");var training=EditorSceneManager.OpenScene(TrainingFlowSession.TrainingScene);var overlay=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();if(overlay==null)throw new Exception("Missing existing training");var c=overlay.player.GetComponent<ArmoredStaticPoseView>().characterProfile;string supported=c.characterId;if(overlay.gameObject.GetComponent<TrainingSceneEntryGate>()==null)overlay.gameObject.AddComponent<TrainingSceneEntryGate>();EditorSceneManager.MarkSceneDirty(training);EditorSceneManager.SaveScene(training);var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject("Title and fighter selection");var menu=root.AddComponent<TrainingFrontMenu>();menu.catalog=AssetDatabase.LoadAssetAtPath<FighterCatalog>("Assets/Shioka/調整Data/Fighter/Catalog.asset");menu.supportedTrainingFighterId=supported;EditorSceneManager.SaveScene(scene,TrainingFlowSession.TitleScene);EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(TrainingFlowSession.TitleScene,true),new EditorBuildSettingsScene(TrainingFlowSession.TrainingScene,true)};AssetDatabase.SaveAssets();Debug.Log("TRAINING_FRONT installed existing training with no fighter setting replacement");}
}
